```python
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b:
            return False           # already in the same group
        self.parent[root_a] = root_b
        return True
```

This is correct but unoptimized: `union` always attaches `root_a` under `root_b` with no regard for which tree is taller, which is exactly the design flaw the next two slides fix.

```python
class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])   # path compression
        return self.parent[x]

    def union(self, a, b):
        root_a, root_b = self.find(a), self.find(b)
        if root_a == root_b:
            return False
        if self.rank[root_a] < self.rank[root_b]:
            root_a, root_b = root_b, root_a
        self.parent[root_b] = root_a          # attach smaller-rank tree under larger
        if self.rank[root_a] == self.rank[root_b]:
            self.rank[root_a] += 1            # height only grows on a tie
        return True
```

The recursive `find` here compresses the *entire* path to the root in one call — every ancestor visited gets repointed directly, not just the immediate parent.
